{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "findTasksBySubject",
      "explanation": "The method concatenates user input into a dynamic SOQL string without using bind variables, risking SOQL injection.",
      "remediation": "Use bind variables or Database.queryWithBinds to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "findTasksBySubject",
      "explanation": "The method does not enforce CRUD and FLS permissions, potentially allowing access to data the user should not see.",
      "remediation": "Use Security.stripInaccessible to enforce CRUD and FLS permissions on the query results."
    }
  ]
}

